const RULES=['HOSA Medical Law & Ethics 2026–27 guidelines','https://hosa.org/wp-content/uploads/2026/08/MLE-26-27.pdf'];
const COURTS=['United States Courts: court role and structure','https://www.uscourts.gov/about-federal-courts/court-role-and-structure'];
const PRIV=['HHS: summary of the HIPAA Privacy Rule','https://www.hhs.gov/hipaa/for-professionals/privacy/laws-regulations/index.html'];
const CONSENT=['AMA: informed consent','https://code-medical-ethics.ama-assn.org/ethics-opinions/informed-consent'];
const CAPACITY=['AMA: decisions for adults who lack capacity','https://code-medical-ethics.ama-assn.org/ethics-opinions/decisions-adult-patients-who-lack-capacity'];
const BELMONT=['HHS: Belmont Report','https://www.hhs.gov/ohrp/regulations-and-policy/belmont-report/read-the-belmont-report/index.html'];
